/** Meta App Review may return legacy or business-prefixed Instagram scope names. */
export const META_SCOPE_ALIASES: Record<string, readonly string[]> = {
  instagram_manage_messages: ["instagram_business_manage_messages"],
  instagram_business_manage_messages: ["instagram_manage_messages"],
  instagram_basic: ["instagram_business_basic"],
  instagram_business_basic: ["instagram_basic"],
};

export const META_PENDING_APP_REVIEW_SCOPES = [
  "instagram_manage_comments",
  "pages_manage_engagement",
  "instagram_manage_insights",
  "pages_read_engagement",
  "instagram_content_publish",
  "pages_manage_posts",
  "business_management",
] as const;

function scopeAliasVariants(scope: string): string[] {
  const key = scope.toLowerCase();
  const aliases = META_SCOPE_ALIASES[key] ?? [];
  return [scope, ...aliases];
}

function isScopeGranted(grantedSet: Set<string>, requiredScope: string): boolean {
  return scopeAliasVariants(requiredScope).some((s) => grantedSet.has(s.toLowerCase()));
}

export function normalizeGrantedScopes(granted: string[]): string[] {
  const result = new Set<string>();
  for (const raw of granted) {
    const trimmed = raw.trim();
    if (!trimmed) continue;
    for (const variant of scopeAliasVariants(trimmed)) {
      result.add(variant);
    }
  }
  return [...result];
}

export function isPendingAppReviewScope(scope: string): boolean {
  const lower = scope.toLowerCase();
  return META_PENDING_APP_REVIEW_SCOPES.some((s) => s.toLowerCase() === lower);
}

export const THREADS_OAUTH_SCOPE_LIST = [
  "threads_basic",
  "threads_manage_insights",
  "threads_read_replies",
  "threads_manage_replies",
  "threads_content_publish",
] as const;

export function hasThreadsScopes(granted: string[]): boolean {
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return THREADS_OAUTH_SCOPE_LIST.some((s) => grantedSet.has(s.toLowerCase()));
}

export function metaGraphVersion(): string {
  return Deno.env.get("META_GRAPH_API_VERSION")?.trim() || "v22.0";
}

export function missingScopesForFeature(
  granted: string[],
  feature: keyof typeof META_SCOPE_FEATURE_MAP,
): string[] {
  const required = META_SCOPE_FEATURE_MAP[feature];
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.filter((s) => !isScopeGranted(grantedSet, s));
}

export function hasAllScopes(granted: string[], required: readonly string[]): boolean {
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.every((s) => isScopeGranted(grantedSet, s));
}

export function missingScopesForInstagramPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "publish");
}

export function missingScopesForFacebookPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "facebook_publish");
}

export function instagramPublishScopesOk(granted: string[]): boolean {
  return missingScopesForInstagramPublish(granted).length === 0;
}

export function facebookPublishScopesOk(granted: string[]): boolean {
  return missingScopesForFacebookPublish(granted).length === 0;
}

export async function fetchGrantedPermissions(
  accessToken: string,
  appId?: string,
): Promise<string[]> {
  const version = metaGraphVersion();
  const debugUrl = appId?.trim()
    ? `https://graph.facebook.com/${version}/debug_token?input_token=${encodeURIComponent(accessToken)}&access_token=${encodeURIComponent(appId)}|${encodeURIComponent(Deno.env.get("META_APP_SECRET") ?? "")}`
    : null;

  if (debugUrl) {
    try {
      const res = await fetch(debugUrl);
      const data = await res.json().catch(() => ({})) as {
        data?: { scopes?: string[] };
      };
      if (res.ok && Array.isArray(data?.data?.scopes)) {
        return data.data.scopes.map((s) => String(s));
      }
    } catch {
      /* fall through */
    }
  }

  const permUrl = `https://graph.facebook.com/${version}/me/permissions?access_token=${encodeURIComponent(accessToken)}`;
  const permRes = await fetch(permUrl);
  const permData = await permRes.json().catch(() => ({})) as {
    data?: Array<{ permission?: string; status?: string }>;
  };
  if (!permRes.ok || !Array.isArray(permData?.data)) return [];
  return permData.data
    .filter((p) => p.status === "granted" && p.permission)
    .map((p) => String(p.permission));
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const STATUS_MAP: Record<string, string[]> = {
  new: ["Open", "New"],
  contacted: ["On Progress", "Contacted", "In Progress"],
  deal: ["Converted", "Deal", "Closed Won"],
  lost: ["Lost", "Closed", "Closed Lost"],
};

export async function resolveLeadStatusId(
  admin: SupabaseClient,
  organizationId: string,
  apiStatus?: string | null,
): Promise<string | null> {
  const key = (apiStatus ?? "new").trim().toLowerCase();
  const candidates = STATUS_MAP[key] ?? STATUS_MAP.new;

  for (const name of candidates) {
    const { data } = await admin
      .from("lead_statuses")
      .select("id")
      .eq("organization_id", organizationId)
      .ilike("name", name)
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    if (data?.id) return data.id as string;
  }

  const { data: fallback } = await admin
    .from("lead_statuses")
    .select("id")
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .order("sort_order", { ascending: true })
    .limit(1)
    .maybeSingle();

  return (fallback?.id as string | undefined) ?? null;
}

export async function resolveConvertedStatusId(
  admin: SupabaseClient,
  organizationId: string,
): Promise<string | null> {
  return resolveLeadStatusId(admin, organizationId, "deal");
}

export async function getOrCreateSystemActor(
  admin: SupabaseClient,
  organizationId: string,
): Promise<{ userId: string; displayName: string }> {
  const { data, error } = await admin.rpc("get_or_create_org_api_system_actor", {
    p_organization_id: organizationId,
  });

  if (error) throw error;
  const row = Array.isArray(data) ? data[0] : data;
  if (!row?.user_id) {
    throw new Error("System actor tidak ditemukan untuk organisasi ini.");
  }
  return {
    userId: String(row.user_id),
    displayName: String(row.display_name ?? "Synckerja API"),
  };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetCampaignRow, LeadMagnetPlatform } from "./types.ts";
import { commentMatchesKeyword } from "./types.ts";

export type MatchedCampaign = LeadMagnetCampaignRow & {
  posts: Array<{ media_id: string }>;
};

export async function findMatchingLeadMagnetCampaign(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    platform: LeadMagnetPlatform;
    accountId: string;
    mediaId: string;
    commentText: string;
  },
): Promise<MatchedCampaign | null> {
  const { data: campaigns, error } = await admin
    .from("lead_magnet_campaigns")
    .select("*")
    .eq("organization_id", args.organizationId)
    .eq("platform", args.platform)
    .eq("account_id", args.accountId)
    .eq("status", "active");

  if (error || !campaigns?.length) return null;

  for (const campaign of campaigns as LeadMagnetCampaignRow[]) {
    if (!commentMatchesKeyword(args.commentText, campaign.keyword)) continue;

    const { data: posts } = await admin
      .from("lead_magnet_campaign_posts")
      .select("media_id")
      .eq("campaign_id", campaign.id)
      .eq("media_id", args.mediaId);

    if (!posts?.length) continue;

    return { ...campaign, posts };
  }

  return null;
}

export async function enrollmentExists(
  admin: SupabaseClient,
  campaignId: string,
  participantScopedId: string,
): Promise<boolean> {
  const { data } = await admin
    .from("lead_magnet_enrollments")
    .select("id")
    .eq("campaign_id", campaignId)
    .eq("participant_scoped_id", participantScopedId)
    .maybeSingle();
  return Boolean(data?.id);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { replyMetaComment } from "../metaContentApi.ts";
import { enrollmentExists, findMatchingLeadMagnetCampaign } from "./campaignMatcher.ts";
import { createLeadMagnetLead } from "./createLeadMagnetLead.ts";
import { fetchCommentText } from "./fetchParticipantProfile.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "./funnelAnalytics.ts";
import { runFollowCheckAndDmFlow } from "./followGateRuntime.ts";
import type { LeadMagnetCommentTriggerInput } from "./types.ts";

export async function handleLeadMagnetCommentTrigger(
  admin: SupabaseClient,
  input: LeadMagnetCommentTriggerInput,
): Promise<boolean> {
  let commentText = input.commentText.trim();
  let authorUsername = input.authorUsername;

  if (!commentText) {
    const fetched = await fetchCommentText(input.commentId, input.accessToken);
    commentText = (fetched.text ?? "").trim();
    if (!authorUsername && fetched.username) authorUsername = fetched.username;
  }

  if (!commentText) {
    console.log("[lead-magnet] skip comment without text", input.commentId);
    return false;
  }

  const campaign = await findMatchingLeadMagnetCampaign(admin, {
    organizationId: input.organizationId,
    platform: input.platform,
    accountId: input.accountId,
    mediaId: input.mediaId,
    commentText,
  });

  if (!campaign) return false;

  const exists = await enrollmentExists(admin, campaign.id, input.authorScopedId);
  if (exists) {
    console.log("[lead-magnet] dedup skip", campaign.id, input.authorScopedId);
    return true;
  }

  const enrollmentId = crypto.randomUUID();
  const now = new Date().toISOString();

  const { error: enrollErr } = await admin.from("lead_magnet_enrollments").insert({
    id: enrollmentId,
    organization_id: input.organizationId,
    campaign_id: campaign.id,
    platform: input.platform,
    participant_scoped_id: input.authorScopedId,
    participant_username: authorUsername,
    comment_id: input.commentId,
    media_id: input.mediaId,
    status: "comment_matched",
    created_at: now,
    updated_at: now,
  });

  if (enrollErr) {
    if (enrollErr.code === "23505") return true;
    console.error("[lead-magnet] enrollment insert failed:", enrollErr.message);
    return false;
  }

  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId,
    campaignId: campaign.id,
    organizationId: input.organizationId,
    eventType: "comment_matched",
    metadata: { comment_id: input.commentId, media_id: input.mediaId },
  });

  await createLeadMagnetLead(admin, {
    organizationId: input.organizationId,
    campaign,
    enrollmentId,
    participantUsername: authorUsername,
    participantScopedId: input.authorScopedId,
    platform: input.platform,
    mediaId: input.mediaId,
  });

  try {
    await replyMetaComment(input.platform, input.commentId, campaign.comment_reply_text, input.accessToken);
    await updateEnrollmentStatus(admin, enrollmentId, "comment_replied");
    await logLeadMagnetFunnelEvent(admin, {
      enrollmentId,
      campaignId: campaign.id,
      organizationId: input.organizationId,
      eventType: "comment_replied",
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error("[lead-magnet] comment reply failed:", msg);
    await updateEnrollmentStatus(admin, enrollmentId, "failed", { last_error: msg });
    return true;
  }

  const { data: enrollment } = await admin
    .from("lead_magnet_enrollments")
    .select("*")
    .eq("id", enrollmentId)
    .single();

  if (enrollment) {
    await runFollowCheckAndDmFlow(admin, {
      enrollment: enrollment as typeof enrollment & { platform: "instagram" | "facebook" },
      campaign,
      accessToken: input.accessToken,
      pageId: input.pageId,
    });
  }

  return true;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getOrCreateSystemActor, resolveLeadStatusId } from "../omnichannelPublicApi/leadStatusMap.ts";
import type { LeadMagnetCampaignRow, LeadMagnetPlatform } from "./types.ts";

async function resolveWebIdForLeadMagnet(
  admin: SupabaseClient,
  organizationId: string,
): Promise<string | null> {
  const { data: rows } = await admin
    .from("analytics_web_access")
    .select("web_id, is_approved")
    .eq("organization_id", organizationId)
    .order("is_approved", { ascending: false })
    .order("web_id", { ascending: true })
    .limit(5);

  if (rows?.length) {
    const approved = rows.find((r) => r.is_approved !== false);
    const webId = (approved ?? rows[0])?.web_id;
    if (webId && String(webId).trim()) return String(webId).trim();
  }

  const { data: sibling } = await admin
    .from("lead_submissions")
    .select("web_id")
    .eq("organization_id", organizationId)
    .not("web_id", "is", null)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (sibling?.web_id && String(sibling.web_id).trim()) {
    return String(sibling.web_id).trim();
  }

  return null;
}

export async function createLeadMagnetLead(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    campaign: LeadMagnetCampaignRow;
    enrollmentId: string;
    participantUsername: string | null;
    participantScopedId: string;
    platform: LeadMagnetPlatform;
    mediaId: string;
  },
): Promise<{ leadId: string; leadSubmissionId: string } | null> {
  try {
    const actor = await getOrCreateSystemActor(admin, args.organizationId);
    const statusId = await resolveLeadStatusId(admin, args.organizationId, "new");
    const webId = await resolveWebIdForLeadMagnet(admin, args.organizationId);
    if (!webId) {
      console.warn("[lead-magnet] no web_id for org, skipping lead_submissions");
      return null;
    }

    const displayName = (args.participantUsername ?? "").trim().replace(/^@/, "") ||
      `IG ${args.participantScopedId.slice(0, 8)}`;
    const now = new Date().toISOString();
    const channelLabel = args.platform === "instagram" ? "Instagram Comment" : "Facebook Comment";

    const leadId = crypto.randomUUID();
    const ticketId = "LEAD-" + leadId.replace(/-/g, "").slice(0, 8).toUpperCase();

    const { error: leadErr } = await admin.from("leads").insert({
      id: leadId,
      ticket_id: ticketId,
      client: displayName,
      title: `Lead Magnet — ${args.campaign.name}`.slice(0, 120),
      category: "Lead Magnet",
      source: "Lead Magnet",
      services: channelLabel,
      organization_id: args.organizationId,
      created_by: actor.userId,
      created_by_name: "",
      assignee: "Unassigned",
      status_id: statusId,
      web_id: webId,
      created_at: now,
      updated_at: now,
    });

    if (leadErr) {
      console.error("[lead-magnet] leads insert failed:", leadErr.message);
      return null;
    }

    const submissionId = crypto.randomUUID();
    const { error: subErr } = await admin.from("lead_submissions").insert({
      id: submissionId,
      organization_id: args.organizationId,
      lead_id: leadId,
      web_id: webId,
      form_id: null,
      name: displayName,
      status: "draft",
      is_active: true,
      lead_magnet_enrollment_id: args.enrollmentId,
      lead_magnet_campaign_id: args.campaign.id,
      notes: `Lead magnet keyword "${args.campaign.keyword}" on media ${args.mediaId}`,
      updated_at: now,
    });

    if (subErr) {
      console.error("[lead-magnet] lead_submissions insert failed:", subErr.message);
      return { leadId, leadSubmissionId: submissionId };
    }

    await admin
      .from("lead_magnet_enrollments")
      .update({ lead_id: leadId, lead_submission_id: submissionId, updated_at: now })
      .eq("id", args.enrollmentId);

    return { leadId, leadSubmissionId: submissionId };
  } catch (err) {
    console.error("[lead-magnet] createLeadMagnetLead error:", err);
    return null;
  }
}

const META_GRAPH_VERSION = "v21.0";

export type ParticipantProfile = {
  username: string | null;
  name: string | null;
  isFollower: boolean | null;
};

export async function fetchParticipantProfile(
  scopedUserId: string,
  accessToken: string,
): Promise<ParticipantProfile> {
  const fields = "username,name,is_user_follow_business";
  const url =
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(scopedUserId)}?fields=${fields}`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const data = await res.json() as {
      username?: string;
      name?: string;
      is_user_follow_business?: boolean;
      error?: { message?: string };
    };
    if (!res.ok) {
      console.warn("[lead-magnet] profile fetch failed:", data.error?.message ?? res.status);
      return { username: null, name: null, isFollower: null };
    }
    return {
      username: typeof data.username === "string" ? data.username : null,
      name: typeof data.name === "string" ? data.name : null,
      isFollower: typeof data.is_user_follow_business === "boolean" ? data.is_user_follow_business : null,
    };
  } catch (err) {
    console.warn("[lead-magnet] profile fetch error:", err);
    return { username: null, name: null, isFollower: null };
  }
}

export async function fetchCommentText(
  commentId: string,
  accessToken: string,
): Promise<{ text: string | null; username: string | null }> {
  const fields = "text,from,username";
  const url =
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(commentId)}?fields=${fields}`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const data = await res.json() as {
      text?: string;
      username?: string;
      from?: { username?: string; name?: string };
      error?: { message?: string };
    };
    if (!res.ok) {
      console.warn("[lead-magnet] comment fetch failed:", data.error?.message ?? res.status);
      return { text: null, username: null };
    }
    const username = data.username ?? data.from?.username ?? null;
    return {
      text: typeof data.text === "string" ? data.text : null,
      username: typeof username === "string" ? username : null,
    };
  } catch (err) {
    console.warn("[lead-magnet] comment fetch error:", err);
    return { text: null, username: null };
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "./types.ts";
import {
  buildLeadMagnetPostbackPayload,
  interpolateLeadMagnetText,
} from "./types.ts";
import { fetchParticipantProfile } from "./fetchParticipantProfile.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "./funnelAnalytics.ts";
import { sendLeadMagnetDm } from "./sendLeadMagnetMessage.ts";

export async function runFollowCheckAndDmFlow(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
  },
): Promise<void> {
  if (args.enrollment.status === "paused" || args.enrollment.status === "delivered" || args.enrollment.status === "failed") {
    return;
  }

  const username = args.enrollment.participant_username;
  let profile = await fetchParticipantProfile(args.enrollment.participant_scoped_id, args.accessToken);
  if (!profile.username && username) profile = { ...profile, username };

  const isFollower = profile.isFollower;
  await updateEnrollmentStatus(admin, args.enrollment.id, "follow_checked", {
    is_follower_at_start: isFollower,
  });
  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: isFollower === null ? "follow_check_failed" : "follow_checked",
    metadata: { is_follower: isFollower },
  });

  if (isFollower === true && args.campaign.skip_follow_gate_if_follower) {
    await sendFrameworkOffer(admin, {
      enrollment: args.enrollment,
      campaign: args.campaign,
      accessToken: args.accessToken,
      pageId: args.pageId,
    });
    return;
  }

  await sendFollowGate(admin, {
    enrollment: args.enrollment,
    campaign: args.campaign,
    accessToken: args.accessToken,
    pageId: args.pageId,
  });
}

export async function sendFollowGate(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
  },
): Promise<void> {
  const text = interpolateLeadMagnetText(args.campaign.follow_gate_text, args.enrollment.participant_username);
  const sendResult = await sendLeadMagnetDm(admin, {
    platform: args.enrollment.platform,
    organizationId: args.enrollment.organization_id,
    accountId: args.campaign.account_id,
    pageId: args.pageId,
    accessToken: args.accessToken,
    recipientScopedId: args.enrollment.participant_scoped_id,
    participantUsername: args.enrollment.participant_username,
    text,
    buttons: [{
      type: "postback",
      title: args.campaign.follow_button_label,
      payload: buildLeadMagnetPostbackPayload(args.enrollment.id, "follow_confirm"),
    }],
    existingConversationId: args.enrollment.conversation_id,
  });

  if (!sendResult.ok) {
    await updateEnrollmentStatus(admin, args.enrollment.id, "failed", {
      last_error: sendResult.error ?? "DM send failed",
      conversation_id: sendResult.conversationId,
      conversation_table: args.enrollment.platform === "instagram"
        ? "instagram_conversations"
        : "facebook_conversations",
    });
    await logLeadMagnetFunnelEvent(admin, {
      enrollmentId: args.enrollment.id,
      campaignId: args.campaign.id,
      organizationId: args.enrollment.organization_id,
      eventType: "dm_failed",
      metadata: { step: "follow_gate", error: sendResult.error, session_expired: sendResult.isSessionExpired },
    });
    return;
  }

  await updateEnrollmentStatus(admin, args.enrollment.id, "follow_gate_sent", {
    conversation_id: sendResult.conversationId,
    conversation_table: args.enrollment.platform === "instagram"
      ? "instagram_conversations"
      : "facebook_conversations",
  });
  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: "follow_gate_sent",
  });
}

